from dataclasses import dataclass


@dataclass(frozen=True)
class Record:
    key: str
    value: int


def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def normalize_records(records):
    """Normalize record dicts into a sorted list of frozen Records.

    Rules:
      - ``records`` must be a list (not tuple/str/dict/set/generator) of dicts.
        A ``dict`` input is iterable over its keys only, so it is malformed.
      - Every row must be a ``dict``.
      - Keys must be ``str``; normalized by ``strip()`` then ``casefold()``.
        An empty normalized key is rejected with ``ValueError``.
      - Values must be ``int`` (``bool`` is invalid).
      - Duplicate normalized keys keep the LAST value.
      - Result is a new list of ``Record`` sorted lexicographically by key.
      - The input (container, rows and nested values) is never mutated.
    """
    if not isinstance(records, list):
        raise ValueError("records must be a list of dictionaries")
    merged = {}
    for index, record in enumerate(records):
        if not isinstance(record, dict):
            raise ValueError(f"row {index} must be a dictionary")
        if "key" not in record or "value" not in record:
            raise ValueError(f"row {index} must contain 'key' and 'value'")
        raw_key = record["key"]
        if not isinstance(raw_key, str):
            raise ValueError(f"row {index} key must be a string")
        key = raw_key.strip().casefold()
        if not key:
            raise ValueError(f"row {index} has an empty normalized key")
        value = record["value"]
        if not _is_int(value):
            raise ValueError(f"row {index} value must be an integer")
        merged[key] = value
    return [Record(key, merged[key]) for key in sorted(merged)]

